+
+    private static final int FIRST_NAME = 0;
+    private static final int LAST_NAME = 1;
+    private static final int SPECIALTIES = 2;
+
+    /** Seed vets ordered by last name: Carter, Douglas, Jenkins, Leary, Ortega, Stevens. */
+    private static final int SEED_VET_COUNT = 6;
+    private static final int ROW_CARTER = 0;
+    private static final int ROW_DOUGLAS = 1;
+    private static final int ROW_LEARY = 3;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinariansLinkLeadsToTheVetsGrid() {
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected a Veterinarians navigation item");
+        assertEquals("vets", link.getPath());
+
+        navigate(VetsView.class);
+
+        GridTester<Grid<Vet>, Vet> grid = vetsGrid();
+        assertEquals("First Name", grid.getHeaderCell(FIRST_NAME));
+        assertEquals("Last Name", grid.getHeaderCell(LAST_NAME));
+        assertEquals("Specialties", grid.getHeaderCell(SPECIALTIES));
+        assertEquals(SEED_VET_COUNT, grid.size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void eachRowShowsNamesAndSpecialties() {
+        navigate(VetsView.class);
+
+        GridTester<Grid<Vet>, Vet> grid = vetsGrid();
+        assertEquals("Helen", grid.getCellText(ROW_LEARY, FIRST_NAME));
+        assertEquals("Leary", grid.getCellText(ROW_LEARY, LAST_NAME));
+        assertEquals("radiology", grid.getCellText(ROW_LEARY, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
