+        navigate(VetsView.class);
+
+        GridTester<Grid<Vet>, Vet> grid = vetsGrid();
+        assertEquals("Carter", grid.getCellText(ROW_CARTER, LAST_NAME));
+        assertEquals("none", grid.getCellText(ROW_CARTER, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        navigate(VetsView.class);
+
+        // Linda Douglas was assigned surgery before dentistry in the seed data.
+        GridTester<Grid<Vet>, Vet> grid = vetsGrid();
+        assertEquals("Douglas", grid.getCellText(ROW_DOUGLAS, LAST_NAME));
